-- ARP -> wARP advanced-model swap for Darlington (r1) + Gateway (r2).
-- Safe to re-run.
begin;

delete from predictions where race_id = (select id from races where chase_round = 1) and model_type = 'advanced';
delete from feature_importances where race_id = (select id from races where chase_round = 1) and model_type = 'advanced';
delete from predictions where race_id = (select id from races where chase_round = 2) and model_type = 'advanced';
delete from feature_importances where race_id = (select id from races where chase_round = 2) and model_type = 'advanced';



update model_scores set cv_mae = 2.301, cv_r2 = 0.807, mae = 7.75, rmse = 9.12, r2 = 0.308, top5_hits = 1, top10_hits = 4, predicted_winner = 'Tyler Reddick', predicted_winner_actual_finish = 3 where race_id = (select id from races where chase_round = 1) and model_type = 'advanced';
commit;
